import{_ as l,l as s,o as e,c as o,v as t,p as d,x as i,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Dial 与堆变体","description":"","frontmatter":{"title":"Dial 与堆变体","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dijkstra-heap.md","filePath":"cs/dijkstra-heap.md","lastUpdated":1789023840000}'),p={name:"cs/dijkstra-heap.md"};function E(D,a,_,m,u,f){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="dial-与堆变体" tabindex="-1">Dial 与堆变体 <a class="header-anchor" href="#dial-与堆变体" aria-label="Permalink to &quot;Dial 与堆变体&quot;">​</a></h1><div class="epigraph"><p>Extract-Min 的实现决定 Dijkstra 的渐近：整数权可用桶，一般非负权用堆；斐波那契堆把减键摊还到均摊常数。</p><footer>—— 据 Dial, Algorithm 360, 1969；Fredman and Tarjan, Fibonacci heaps and their uses, 1987；CLRS 第 24 章整理</footer></div><p>上一课<a href="/cs/dijkstra">Dijkstra</a>钉死非负权上的贪心取出：一旦 Extract-Min 得到 \\(u\\)，\\(d[u]=\\delta(s,u)\\)。实现随口说了二叉堆 \\(O((V+E)\\log V)\\)。本课不重证那条不变式。缺口是<strong>优先队列怎么做</strong>：扫描数组、二叉堆、Dial 桶、斐波那契堆，各在什么权上合法。后课负边仍禁止这些加速。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素每次扫 \\(V\\) 个 \\(d\\) 值，\\(O(V^2+E)\\)，稠密图合适。稀疏图要用堆：<code>Decrease-Key</code> 对应松弛成功。二叉堆上减键 \\(O(\\log V)\\)，总 \\(O((V+E)\\log V)\\)。若边权是 \\(\\{0,1,\\ldots,C\\}\\) 上的整数，Dial：按当前距离把顶点放进 \\(C+1\\) 个循环桶，Extract-Min 是扫桶，单调性来自非负权下 \\(d\\) 只增且步长 \\(\\le C\\)。时间 \\(O(E+VC)\\)。缺口是把「堆」从算法定义里拆出来。</p><p>斐波那契堆：Extract-Min 均摊 \\(O(\\log V)\\)，Decrease-Key 均摊 \\(O(1)\\)，故 \\(O(E+V\\log V)\\)。常数大，课内记上界，实现默认二叉堆。</p><h3 id="dial-不是-bfs-队列" tabindex="-1">Dial 不是 BFS 队列 <a class="header-anchor" href="#dial-不是-bfs-队列" aria-label="Permalink to &quot;Dial 不是 BFS 队列&quot;">​</a></h3><p>权为 \\(1\\) 时 Dial 退化成按层扫，与 BFS 同类，但桶是为整数权准备的。负权仍会破坏取出即钉死，换桶没有用。不要对负权实例「换一个更快的堆」。</p><p><span class="marginnote">Dial 1969 的桶用于整数权最短路。Fredman–Tarjan 1987 用斐波那契堆改进多种图算法。CLRS 24.3 把实现参数化成优先队列。本课不手写斐波那契堆的级联切断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先确认权 \\(\\ge 0\\)。整数且 \\(C\\) 不大：Dial。一般：二叉堆。要写紧的稀疏上界：斐波那契。权全 \\(1\\)：退回<a href="/cs/bfs-unweighted">无权 BFS</a>，不要堆。</p>',11)),(e(),d(h,null,{default:i(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NN%5B%22%E9%9D%9E%E8%B4%9F%E6%9D%83%20Dijkstra%22%5D%20--%3E%20INT%5B%22%E6%95%B4%E6%95%B0%E6%9D%83%20%E2%89%A4%20C%EF%BC%9ADial%20%E6%A1%B6%22%5D%0A%20%20NN%20--%3E%20BIN%5B%22%E4%BA%8C%E5%8F%89%E5%A0%86%22%5D%0A%20%20NN%20--%3E%20FIB%5B%22%E6%96%90%E6%B3%A2%E9%82%A3%E5%A5%91%EF%BC%9AO(E%2BV%20log%20V)%22%5D%0A%20%20NN%20--%3E%20BFS%5B%22%E6%9D%83%3D1%EF%BC%9A%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>正确性全部继承上一课；变的只是取出与减键的代价。减键需要堆内句柄，邻接表顶点要能找到堆节点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单调桶依赖 \\(d[u]\\) 被钉死后不会再减，且新松弛值 \\(\\ge d[u]\\)。这就是非负。势能分析（斐波那契）与<a href="/cs/amortized-analysis">摊还</a>同类，本课不重写势函数。全源非负稀疏图：\\(V\\) 次本算法，堆的选择会被乘 \\(V\\) 倍——<a href="/cs/johnson-apsp">Johnson</a> 再收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理负边、不写 \\(A^*\\)。桶宽 \\(C\\) 随输入指数时 Dial 并不多项式于位数，与背包伪多项式同类，点名即可。后课默认：非负单源实现按权选择队列；负权入口是 Bellman–Ford，不能减键加速。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dijkstra 的渐近 = Extract-Min / Decrease-Key 的代价。</li><li>整数权 Dial；\\(1\\) 权 BFS；一般二叉堆；紧界斐波那契。</li><li>负权使取出即钉死失败，换堆无效。</li><li>出处：Dial, 1969；Fredman and Tarjan, 1987；CLRS 第 24.3 节。</li></ul>',7))])}const V=l(p,[["render",E]]);export{A as __pageData,V as default};
